WITH flattened AS (SELECT id, service, host, level, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS k, v) SELECT id, service, latency_ms, k, v, LAST_VALUE(k) IGNORE NULLS OVER (ORDER BY status_code ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_k, AVG(status_code) OVER (ORDER BY status_code ASC, id ASC, k ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS status_code_avg_5_prior FROM flattened WHERE k = 'trace';
